@extends('layouts.app') @section('title','Kalender Kegiatan') @section('content')<div class="page-head"><div><span class="eyebrow">Kalender Terintegrasi</span><h1>Agenda Rumah Sakit</h1><p>PKL, rotasi, penelitian, pelatihan, dan sidang etik dalam satu tampilan.</p></div></div><section class="panel calendar"><div class="calendar-head"><button>‹</button><h2>{{ now()->translatedFormat('F Y') }}</h2><button>›</button></div><div class="weekdays">@foreach(['Sen','Sel','Rab','Kam','Jum','Sab','Min'] as $d)<b>{{ $d }}</b>@endforeach</div><div class="calendar-grid">@foreach(range(1,35) as $cell) @php($day=$cell-3) <div class="day {{ $day<1||$day>now()->daysInMonth?'muted':'' }}"><span>{{ $day<1?$day+now()->copy()->subMonth()->daysInMonth:($day>now()->daysInMonth?$day-now()->daysInMonth:$day) }}</span>@foreach($activities->filter(fn($activity)=>$activity->start_at->day===$day && $activity->start_at->month===now()->month)->take(3) as $activity)<a class="event blue" title="{{ $activity->title }}">{{ $activity->start_at->format('H:i') }} {{ $activity->title }}</a>@endforeach</div>@endforeach</div></section>@endsection
